function validate([n, leftChild, rightChild]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is between 1 and 10000.';
  if (!Array.isArray(leftChild) || !Array.isArray(rightChild) || leftChild.length !== n || rightChild.length !== n) return 'leftChild and rightChild each need exactly n entries.';
  for (const v of [...leftChild, ...rightChild]) if (!Number.isInteger(v) || v < -1 || v > n - 1) return 'Each child is -1 or a node label from 0 to n - 1.';
  return null;
}

