function validateBinaryTreeNodes(n, leftChild, rightChild) {
  const parents = new Array(n).fill(0);
  for (let node = 0; node < n; node++) {
    for (const child of [leftChild[node], rightChild[node]]) {
      if (child === -1) continue;
      parents[child]++;
      if (parents[child] > 1) return false;
    }
  }

  let root = -1;
  for (let node = 0; node < n; node++) {
    if (parents[node] === 0) {
      if (root !== -1) return false;
      root = node;
    }
  }
  if (root === -1) return false;

  const stack = [root];
  let reached = 0;
  while (stack.length > 0) {
    const node = stack.pop();
    reached++;
    for (const child of [leftChild[node], rightChild[node]]) {
      if (child !== -1) stack.push(child);
    }
  }
  return reached === n;
}

