function validateBinaryTreeNodes(n, leftChild, rightChild) {
  // Try every label as the root; it works if a walk from it meets every node exactly once.
  for (let root = 0; root < n; root++) {
    const hits = new Array(n).fill(0);
    const queue = [root];
    let ok = true;
    for (let q = 0; q < queue.length && ok; q++) {
      const node = queue[q];
      hits[node]++;
      if (hits[node] > 1) ok = false;
      else for (const c of [leftChild[node], rightChild[node]]) if (c !== -1) queue.push(c);
    }
    if (ok && hits.every(h => h === 1)) return true;
  }
  return false;
}

