function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 7);
  const pick = (k) => Math.floor(rand() * k);
  const leftChild = new Array(n).fill(-1);
  const rightChild = new Array(n).fill(-1);
  const parent = new Array(n).fill(-1);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  // Build a valid tree: each node in order hangs from a free slot of an earlier node.
  const deep = rand() < 0.3;
  for (let k = 1; k < n; k++) {
    for (;;) {
      const p = deep ? order[k - 1 - pick(Math.min(k, 2))] : order[pick(k)];
      const first = rand() < 0.5 ? leftChild : rightChild;
      const second = first === leftChild ? rightChild : leftChild;
      if (first[p] === -1) { first[p] = order[k]; parent[order[k]] = p; break; }
      if (second[p] === -1) { second[p] = order[k]; parent[order[k]] = p; break; }
    }
  }
  const root = order[0];
  const freeSlot = (node, target) => { if (leftChild[node] === -1) leftChild[node] = target; else rightChild[node] = target; };
  const mode = rand();
  if (mode < 0.4) return [n, leftChild, rightChild];
  let kind = pick(4);
  if (n === 1) kind = 0;
  if (kind === 3) {
    // The same child in both slots of one node.
    const single = order.filter(v => (leftChild[v] === -1) !== (rightChild[v] === -1));
    if (single.length === 0) kind = 0;
    else { const v = single[pick(single.length)]; if (leftChild[v] === -1) leftChild[v] = rightChild[v]; else rightChild[v] = leftChild[v]; }
  }
  if (kind === 0) {
    // An extra link from a node with a free slot to any node (second parent, cycle or self loop).
    const open = order.filter(v => leftChild[v] === -1 || rightChild[v] === -1);
    freeSlot(open[pick(open.length)], pick(n));
  } else if (kind === 1) {
    // Cut one link: the cut subtree becomes a second root.
    const x = order[1 + pick(n - 1)];
    if (leftChild[parent[x]] === x) leftChild[parent[x]] = -1; else rightChild[parent[x]] = -1;
  } else if (kind === 2) {
    // Detach a subtree and loop it back onto itself: one root, single parents, but not connected.
    const x = order[1 + pick(n - 1)];
    if (leftChild[parent[x]] === x) leftChild[parent[x]] = -1; else rightChild[parent[x]] = -1;
    let d = x;
    while (leftChild[d] !== -1 && rightChild[d] !== -1) d = rand() < 0.5 ? leftChild[d] : rightChild[d];
    freeSlot(d, x);
  }
  return [n, leftChild, rightChild];
}
